package cos.premy.mines.data;
import android.content.Context;
import android.content.SharedPreferences;
import cos.premy.mines.GameStatus;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ModeRulesTest {
 private GameStatus status(int layers){Context c=mock(Context.class);SharedPreferences p=mock(SharedPreferences.class);when(c.getSharedPreferences("cos.premy.mines.settings",0)).thenReturn(p);return new GameStatus(c,layers,layers-1,0,0);}
 @Test public void everyAuthoredLogicLevelHasACompletePublicProof(){for(int level=0;level<3;level++){BoardDefinition b=new BoardDefinition("puzzle",5,level==0?2:3,new int[]{7,11,14}[level],level,new long[]{1500,2500,3501}[level],"");assertTrue("Level "+level,LogicSolver.verifies(b));}}
 @Test public void faultsRemoveCellsFromSymmetricSixNeighborTopology(){for(int level=0;level<3;level++){BoardDefinition b=new BoardDefinition("fault",5,3,9,level,17,"");for(int i=0;i<b.present.length;i++){int[] n=b.neighbors(i);assertTrue(n.length<=6);if(!b.present[i])assertEquals(0,n.length);for(int other:n){assertTrue(b.present[other]);boolean reciprocal=false;for(int back:b.neighbors(other))if(back==i)reciprocal=true;assertTrue(reciprocal);MineCoord a=b.coord(i),c=b.coord(other);assertEquals(1,Math.abs(a.x-c.x)+Math.abs(a.y-c.y)+Math.abs(a.z-c.z));}}}}
 @Test public void holesRejectMovesAndRestoreWithoutInventingCells(){BoardDefinition d=new BoardDefinition("fault",5,3,9,1,31,"");MinesContainer b=new MinesContainer(5,5,3,9);b.configure(d);GameStatus s=status(3);BoardMoves m=new BoardMoves(b,s);assertTrue(m.open(new MineCoord(2,2,2)).isEmpty());assertFalse(m.toggleFlag(new MineCoord(2,2,2)));m.open(new MineCoord(0,0,2));byte[] data=b.saveCells();MinesContainer restored=MinesContainer.restore(d,true,data);assertNotNull(restored);assertArrayEquals(data,restored.saveCells());data[d.index(2,2,2)]=4;assertNull(MinesContainer.restore(d,true,data));}
 @Test public void dailyBoardAndStartAreStableAcrossRetry(){String day="2026-11-13";BoardDefinition a=new BoardDefinition("daily",5,3,10,0,BoardDefinition.dailySeed(day),day),b=new BoardDefinition("daily",5,3,10,0,BoardDefinition.dailySeed(day),day),next=new BoardDefinition("daily",5,3,10,0,BoardDefinition.dailySeed("2026-11-14"),"2026-11-14");assertArrayEquals(a.mineLayout(a.start),b.mineLayout(b.start));assertFalse(Arrays.equals(a.mineLayout(a.start),next.mineLayout(next.start)));assertFalse(a.mineLayout(a.start)[a.start]);assertEquals(0,a.clues(a.mineLayout(a.start))[a.start]);}
 @Test public void escapeWinsFromOpenedRouteNotFlags(){for(int level=0;level<3;level++){BoardDefinition d=new BoardDefinition("escape",5,level==0?2:3,new int[]{4,9,8}[level],level,new long[]{1500,2505,3508}[level],"");MinesContainer b=new MinesContainer(5,5,d.layers,d.mines);b.configure(d);b.generate(d.coord(d.start));GameStatus s=status(d.layers);BoardMoves moves=new BoardMoves(b,s);boolean[] truth=d.mineLayout(d.start);for(int i=0;i<truth.length;i++)if(truth[i]){MineCoord c=d.coord(i);s.setLevel(c.z);moves.toggleFlag(c);}assertTrue(s.stillPlaying());int[] prev=new int[truth.length];Arrays.fill(prev,-1);ArrayDeque<Integer> q=new ArrayDeque<>();q.add(d.start);prev[d.start]=d.start;while(!q.isEmpty()){int id=q.remove();for(int n:d.neighbors(id))if(!truth[n]&&prev[n]<0){prev[n]=id;q.add(n);}}assertTrue(prev[d.exit]>=0);List<Integer> path=new ArrayList<>();for(int id=d.exit;;id=prev[id]){path.add(id);if(id==d.start)break;}Collections.reverse(path);for(int n=0;n<path.size();n++){MineCoord c=d.coord(path.get(n));s.setLevel(c.z);moves.open(c);assertEquals(n==path.size()-1,s.hasUserWon());}assertEquals(1,s.outcome());}}
 @Test public void publicHintsDoNotAssumeThatPlayerFlagsAreCorrect(){BoardDefinition d=new BoardDefinition("puzzle",5,2,7,0,1500,"");int[] visible=new int[50];Arrays.fill(visible,-1);visible[d.start]=0;boolean[] flags=new boolean[50];for(int n:d.neighbors(d.start))flags[n]=true;LogicSolver.Hint h=LogicSolver.next(d,visible,flags);assertNotNull(h);assertFalse(h.mine);assertTrue(flags[h.cell]);}
 @Test public void maxBoardGenerationKeeps540MinesAndFirstOpenSafe(){for(long seed=0;seed<30;seed++){BoardDefinition d=new BoardDefinition("classic",15,8,540,0,seed,"");int safe=(int)(seed*59)%1800;boolean[] layout=d.mineLayout(safe);assertFalse(layout[safe]);int n=0;for(boolean mine:layout)if(mine)n++;assertEquals(540,n);}}
 @Test public void secondEscapeRequiresNumberReasoningRatherThanAnAllZeroWalk(){BoardDefinition d=new BoardDefinition("escape",5,3,9,1,2505,"");boolean[] truth=d.mineLayout(d.start),seen=new boolean[75];int[] clues=d.clues(truth);ArrayDeque<Integer> q=new ArrayDeque<>();q.add(d.start);seen[d.start]=true;while(!q.isEmpty()){int id=q.remove();if(clues[id]!=0)continue;for(int n:d.neighbors(id))if(!seen[n]){seen[n]=true;q.add(n);}}assertFalse(seen[d.exit]);assertTrue(LogicSolver.verifies(d));}
}



